INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 7, 0, 7001, 1, "2030/12/17 14:59:59", 106001, 0.0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 7, 0, 7002, 1, "2030/12/17 14:59:59", 105901, 0.0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 7, 0, 7003, 1, "2030/12/17 14:59:59", 105801, 0.0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 10, 0, 10001, 1, "2030/12/17 14:59:59", 105801, 0.0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 10, 0, 10002, 1, "2030/12/17 14:59:59", 106001, 0.0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 10, 0, 10003, 1, "2030/12/17 14:59:59", 105901, 0.0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 10, 2104010, 10004, 2, "2030/12/17 14:59:59", 106401, 0.0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "ペコリーヌ", 12, 0, 12001, 1, "2030/12/17 14:59:59", 105801, 0.0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 13, 0, 13001, 1, "2030/12/17 14:59:59", 106001, 0.0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 13, 0, 13002, 1, "2030/12/17 14:59:59", 105901, 0.0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 13, 2104010, 13003, 2, "2030/12/17 14:59:59", 106401, 0.0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 13, 0, 13004, 1, "2030/12/17 14:59:59", 105801, 0.0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 14, 0, 14001, 1, "2030/12/17 14:59:59", 105901, 0.0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 14, 2104010, 14002, 2, "2030/12/17 14:59:59", 106401, 0.0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 14, 0, 14003, 1, "2030/12/17 14:59:59", 105801, 0.0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 14, 0, 14004, 1, "2030/12/17 14:59:59", 106001, 0.0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -470.0, "2015/12/17 15:00:00", "コッコロ", 15, 0, 15001, 1, "2030/12/17 14:59:59", 105901, 0.0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 16, 2104010, 16001, 2, "2030/12/17 14:59:59", 106401, 0.0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 16, 0, 16002, 1, "2030/12/17 14:59:59", 105801, 0.0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 16, 0, 16003, 1, "2030/12/17 14:59:59", 106001, 0.0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 16, 0, 16004, 1, "2030/12/17 14:59:59", 105901, 0.0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 17, 0, 17002, 1, "2030/12/17 14:59:59", 105901, 0.0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 25, 0, 17004, 1, "2030/12/17 14:59:59", 106001, 0.0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 25, 0, 17005, 1, "2030/12/17 14:59:59", 105901, 0.0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 25, 2104010, 17006, 2, "2030/12/17 14:59:59", 106401, 0.0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 25, 0, 17007, 1, "2030/12/17 14:59:59", 105801, 0.0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "カリン", 18, 0, 18001, 1, "2030/12/17 14:59:59", 190801, 0.0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -363.0, "2015/12/17 15:00:00", "カリン", 18, 0, 18002, 1, "2030/12/17 14:59:59", 190801, 0.0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 0.0, 0, -470.0, "2015/12/17 15:00:00", "カリン", 19, 0, 19001, 1, "2030/12/17 14:59:59", 190801, 0.0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 0.0, 0, -470.0, "2015/12/17 15:00:00", "カリン", 19, 0, 19002, 1, "2030/12/17 14:59:59", 190801, 0.0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (5, 0.0, 0, -470.0, "2015/12/17 15:00:00", "カリン", 20, 0, 20001, 1, "2030/12/17 14:59:59", 190801, 0.0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (6, 0.0, 0, -470.0, "2015/12/17 15:00:00", "カリン", 20, 0, 20002, 1, "2030/12/17 14:59:59", 190801, 0.0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 21, 0, 21001, 1, "2030/12/17 14:59:59", 106001, 0.0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 21, 0, 21002, 1, "2030/12/17 14:59:59", 105901, 0.0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 21, 2104010, 21003, 2, "2030/12/17 14:59:59", 106401, 0.0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 21, 0, 21004, 1, "2030/12/17 14:59:59", 105801, 0.0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -430.0, "2015/12/17 15:00:00", "カリン", 22, 0, 22001, 1, "2030/12/17 14:59:59", 190801, 0.0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -430.0, "2015/12/17 15:00:00", "カリン", 22, 0, 22002, 1, "2030/12/17 14:59:59", 190801, 0.0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 0.0, 0, -430.0, "2015/12/17 15:00:00", "カリン", 23, 0, 23001, 1, "2030/12/17 14:59:59", 190801, 0.0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 0.0, 0, -430.0, "2015/12/17 15:00:00", "カリン", 23, 0, 23002, 1, "2030/12/17 14:59:59", 190801, 0.0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24001, 1, "2030/12/17 14:59:59", 109001, 4.08, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24002, 1, "2030/12/17 14:59:59", 109001, 5.0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24003, 1, "2030/12/17 14:59:59", 109001, 10.11, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24004, 1, "2030/12/17 14:59:59", 109001, 4.0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (5, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24005, 1, "2030/12/17 14:59:59", 109001, 6.0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (6, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24006, 1, "2030/12/17 14:59:59", 109002, 0.0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24007, 1, "2030/12/17 14:59:59", 109002, 0.0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (8, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24008, 1, "2030/12/17 14:59:59", 109002, 0.0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (9, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24009, 1, "2030/12/17 14:59:59", 109002, 0.0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "エリコ（バレンタイン）", 24, 0, 24010, 1, "2030/12/17 14:59:59", 109002, 0.0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24011, 1, "2030/12/17 14:59:59", 109101, 2.12, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24012, 5, "2030/12/17 14:59:59", 109101, 4.19, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24013, 2, "2030/12/17 14:59:59", 109101, 2.3, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24014, 1, "2030/12/17 14:59:59", 109102, 0.0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (5, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24015, 5, "2030/12/17 14:59:59", 109101, 5.23, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (6, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24016, 1, "2030/12/17 14:59:59", 109102, 0.0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 8.0, 10011, -385.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24017, 1, "2030/12/17 14:59:59", 109101, 5.01, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (8, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24018, 1, "2030/12/17 14:59:59", 109102, 0.0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (9, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24019, 1, "2030/12/17 14:59:59", 109102, 0.0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 0.0, 10011, 0.0, "2019/01/31 12:00:00", "シズル（バレンタイン）", 24, 0, 24020, 1, "2030/12/17 14:59:59", 109102, 0.0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 26, 2104010, 26001, 2, "2030/12/17 14:59:59", 106401, 0.0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 26, 0, 26002, 1, "2030/12/17 14:59:59", 105801, 0.0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 26, 0, 26003, 1, "2030/12/17 14:59:59", 106001, 0.0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 26, 0, 26004, 1, "2030/12/17 14:59:59", 105901, 0.0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 27, 2104010, 27001, 2, "2030/12/17 14:59:59", 106401, 0.0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 27, 0, 27002, 1, "2030/12/17 14:59:59", 105801, 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 27, 0, 27003, 1, "2030/12/17 14:59:59", 106001, 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 27, 0, 27004, 1, "2030/12/17 14:59:59", 105901, 0.0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2019/09/24 15:00:00", "カリン", 28, 0, 28001, 1, "2030/12/17 14:59:59", 190801, 0.0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -363.0, "2019/09/24 15:00:00", "カリン", 28, 0, 28002, 1, "2030/12/17 14:59:59", 190801, 0.0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 0.0, 0, -409.0, "2019/09/24 15:00:00", "カリン", 29, 0, 29001, 1, "2030/12/17 14:59:59", 190801, 0.0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 0.0, 0, -409.0, "2019/09/24 15:00:00", "カリン", 29, 0, 29002, 1, "2030/12/17 14:59:59", 190801, 0.0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (5, 0.0, 0, -409.0, "2019/09/24 15:00:00", "カリン", 30, 0, 30001, 1, "2030/12/17 14:59:59", 190801, 0.0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (6, 0.0, 0, -409.0, "2019/09/24 15:00:00", "カリン", 30, 0, 30002, 1, "2030/12/17 14:59:59", 190801, 0.0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 0.0, 0, -409.0, "2019/10/31 12:00:00", "カリン", 31, 0, 31001, 1, "2030/12/17 14:59:59", 190801, 0.0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (8, 0.0, 0, -409.0, "2019/10/31 12:00:00", "カリン", 31, 0, 31002, 1, "2030/12/17 14:59:59", 190801, 0.0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -409.0, "2019/12/20 5:00:00", "カリン", 32, 0, 32001, 1, "2020/01/04 4:59:59", 190801, 0.0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -409.0, "2019/12/20 5:00:00", "カリン", 32, 0, 32002, 1, "2020/01/04 4:59:59", 190801, 0.0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 0.0, 0, -409.0, "2019/12/20 5:00:00", "カリン", 33, 0, 33001, 1, "2020/01/04 4:59:59", 190801, 0.0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 0.0, 0, -409.0, "2019/12/20 5:00:00", "カリン", 33, 0, 33002, 1, "2020/01/04 4:59:59", 190801, 0.0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (5, 0.0, 0, -409.0, "2020/01/04 5:00:00", "カリン", 34, 0, 34001, 1, "2020/01/10 11:59:59", 190801, 0.0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (6, 0.0, 0, -409.0, "2020/01/04 5:00:00", "カリン", 34, 0, 34002, 1, "2020/01/10 11:59:59", 190801, 0.0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -458.0, "2015/12/17 15:00:00", "ペコリーヌ", 38, 0, 38001, 1, "2030/12/17 14:59:59", 105801, 5.3, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -458.0, "2015/12/17 15:00:00", "ペコリーヌ", 38, 0, 38002, 1, "2030/12/17 14:59:59", 105801, 6.5, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, 9999.0, 0, 9999.0, "2020/04/01", "ペコリーヌ", 39, 0, 39005, 3, "2020/04/08 23:59:59", 105801, 0.0, "", 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -430.0, "2015/12/17 15:00:00", "カリン", 40, 0, 40001, 1, "2030/12/17 14:59:59", 190801, 0.0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "シェフィ", 41, 2104010, 41001, 1, "2030/12/17 14:59:59", 106401, 0.0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 41, 0, 41002, 1, "2030/12/17 14:59:59", 105801, 0.0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 41, 0, 41003, 1, "2030/12/17 14:59:59", 106001, 0.0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 41, 0, 41004, 1, "2030/12/17 14:59:59", 105901, 0.0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "コッコロ", 42, 0, 42001, 1, "2030/12/17 14:59:59", 105901, 0.0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "シェフィ", 42, 2104010, 42002, 1, "2030/12/17 14:59:59", 106401, 0.0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "ペコリーヌ", 42, 0, 42003, 1, "2030/12/17 14:59:59", 105801, 0.0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "キャル", 42, 0, 42004, 1, "2030/12/17 14:59:59", 106001, 0.0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "ペコリーヌ", 43, 0, 43001, 1, "2030/12/17 14:59:59", 105801, 0.0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "コッコロ", 43, 0, 43002, 1, "2030/12/17 14:59:59", 105901, 0.0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -363.0, "2015/12/17 15:00:00", "キャル", 43, 0, 43003, 1, "2030/12/17 14:59:59", 106001, 0.0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "アメス", 44, 0, 43004, 1, "2030/12/17 14:59:59", 123001, 0.0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, 0, -416.5, "2015/12/17 15:00:00", "アメス", 44, 0, 43005, 1, "2030/12/17 14:59:59", 123001, 0.0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 0.0, 0, -416.5, "2015/12/17 15:00:00", "アメス", 45, 0, 43006, 1, "2030/12/17 14:59:59", 123001, 5.79, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -371.5, "2015/12/17 15:00:00", "アメス", 46, 0, 46001, 1, "2030/12/17 14:59:59", 123001, 0.0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "シズル", 47, 0, 47001, 2, "2030/12/17 14:59:59", 104901, 0.0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, 0, -416.5, "2015/12/17 15:00:00", "リノ", 47, 0, 47002, 1, "2030/12/17 14:59:59", 101101, 9.32, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 2);
